const {chromium}=require('playwright-core'),fs=require('fs'),path=require('path'),assert=require('assert/strict');const{pathToFileURL}=require('url');
const root=__dirname,out=path.join(root,'evidence-review-20261106');fs.mkdirSync(out,{recursive:true});
(async()=>{const b=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'}),p=await b.newPage({viewport:{width:1480,height:1140}}),errors=[],results=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(pathToFileURL(path.join(root,'Steam接入Demo.html')).href);
const api=(n,a)=>p.evaluate(([n,a])=>demo[n](a),[n,a]),get=()=>api('getState'),click=a=>p.locator('#screen [data-action="'+a+'"]:not([inert] *)').first().click();
const test=async(name,fn)=>{try{await api('reset');await fn();results.push({name,status:'passed'});console.log('PASS '+name)}catch(e){results.push({name,status:'failed',message:e.message});console.error('FAIL '+name+' '+e.message)}};
const prepare=async()=>{for(let i=0;i<8;i++){if(['steam','login'].includes((await get()).page))return;await api('advance')}throw Error('prepare timeout')};
await test('统一协议前置，未勾选禁用',async()=>{await click('enter-steam');assert.equal((await get()).page,'mode');assert(await p.locator('[data-action="confirm-mode"]').isDisabled());await p.locator('#consent').check();await click('confirm-mode');assert.equal((await get()).page,'prepare');await prepare();assert.equal((await get()).page,'login')});
await test('非WiFi确认前不下载，拒绝停止，接受继续',async()=>{await api('loadFixture','cellular-download');await api('advance');assert.equal((await get()).stage,'cellular');await click('entry-cancel');assert.equal((await get()).page,'library');assert.equal((await get()).prepareActive,false);await api('loadFixture','cellular-download');await click('data-download');await p.waitForTimeout(480);assert((await get()).progress>0);await click('entry-cancel');const before=await get();await p.waitForTimeout(1250);assert.equal((await get()).progress,before.progress);assert.equal((await get()).page,'library')});
await test('背景不取消，Esc取消；下载切流量重新确认',async()=>{await api('loadFixture','downloading');await p.locator('.prepare-overlay').click({position:{x:50,y:100}});assert.equal((await get()).page,'prepare');await p.keyboard.press('Escape');assert.equal((await get()).page,'library');await api('loadFixture','downloading');await api('setReviewOpen',true);await p.locator('[data-action="connection-toggle"]').click();assert.equal((await get()).stage,'cellular');const value=(await get()).progress;await p.waitForTimeout(600);assert.equal((await get()).progress,value);await api('setReviewOpen',false);await click('data-download');await p.waitForTimeout(450);assert((await get()).progress>value);await click('entry-cancel')});
await test('下载与校验取消后无迟到跳转，不保留启动意图',async()=>{await click('launch-host-game');await p.locator('#consent').check();await click('confirm-mode');await click('entry-cancel');await api('advance');await p.waitForTimeout(1300);assert.equal((await get()).page,'library');assert.equal((await get()).pendingGame,null);assert.equal((await get()).autoLaunch,false);await api('loadFixture','verifying');await click('entry-cancel');await p.waitForTimeout(1250);assert.equal((await get()).page,'library')});
await test('协议与准备取消返回原来源',async()=>{await api('loadFixture','home');await api('enter');assert.equal((await get()).page,'mode');await click('entry-cancel');assert.equal((await get()).page,'home');await api('enter');await p.locator('#consent').check();await click('confirm-mode');await click('entry-cancel');assert.equal((await get()).page,'home')});
await test('本地导入不拦截、不进Steam或伪造同步分类',async()=>{await p.locator('[data-action="launch-host-game"][data-game="hades"]').click();assert.equal((await get()).page,'library');assert.equal((await get()).localLaunch,'hades');assert.equal((await get()).pref.accepted,0);assert.equal((await get()).prepareActive,false);await api('loadFixture','steam-library');assert.equal(await p.locator('[data-action="meeting-source"]').count(),0);assert.equal((await api('getFixtures')).filter(x=>/同步|盖世导入/.test(x.label)).length,0)});
await test('未知状态展示下载/更新组件，组件就绪后已有游戏不重复下载',async()=>{assert((await p.locator('#screen').innerText()).includes('下载组件'));await api('loadFixture','component-update');assert((await p.locator('#screen').innerText()).includes('更新组件'));await api('loadFixture','library-account');assert(!(await p.locator('#screen').innerText()).includes('下载组件'));await p.locator('[data-action="launch-host-game"][data-game="elden"]').click();assert.equal((await get()).page,'steam');assert.equal((await get()).gameStatus,'waiting');assert.equal((await get()).prepareActive,false)});
await test('下载失败重试与有效会话恢复模式',async()=>{await api('loadFixture','network');await api('setScenario','normal');await click('download-control');assert.equal((await get()).stage,'downloading');await api('loadFixture','bubble-settings');await click('bubble-main');await click('library');await click('enter-steam');assert.equal((await get()).currentMode,'window')});
await test('全部演示状态正常渲染',async()=>{for(const f of await api('getFixtures')){await api('loadFixture',f.key);assert(await p.locator('#screen').innerText(),f.key)}assert.equal(errors.length,0,errors.join('\n'))});
for(const [name,key,orientation]of [['01-library','library'],['02-consent','first-mode'],['03-prepare','downloading'],['04-steam','steam-library'],['05-bubble','bubble-open'],['05-bubble-settings','bubble-settings'],['09-login','qr-ready'],['14-bubble-minimized','bubble-mini'],['28-library-account','library-account'],['31-landing-guide','landing-guide'],['36-bubble-landscape','bubble-open','landscape'],['37-bubble-scale150','bubble-scale150'],['50-cellular-download','cellular-download'],['51-component-update','component-update'],['52-local-import','imported-game'],['48-network-failed','steam-network-error'],['40-account-manager','account-manager'],['41-account-import','account-import'],['42-account-import-list','account-import-list'],['45-account-imported','account-imported']]){await api('setOrientation',orientation||'portrait');await api('loadFixture',key);await api('setReviewOpen',false);await p.locator('#viewLabel').click();await p.locator('#screen').screenshot({path:path.join(out,name+'.png')})}
await b.close();fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify({results,errors},null,2));if(results.some(x=>x.status==='failed')||errors.length)process.exitCode=1;
})();
